// Parses two live Confluence pages on every run:
//   General tools (internal)     (2076311575)  - the tool checklist (internal source page, includes [internal] columns)
//   Offboarding additional steps (2003894274) - extra steps appended at the bottom
const mainPage = $('Fetch General tools page').first().json;
const extraPage = $input.first().json;

function textOf(n) {
  if (!n) { return ''; }
  if (n.type === 'text') { return n.text || ''; }
  if (n.type === 'status') { return (n.attrs && n.attrs.text) ? n.attrs.text : ''; }
  if (n.type === 'inlineCard' || n.type === 'blockCard') { return (n.attrs && n.attrs.url) ? n.attrs.url : ''; }
  let out = '';
  const kids = n.content || [];
  for (let i = 0; i < kids.length; i++) { out += textOf(kids[i]); }
  return out;
}

// Pulls hyperlinks out of a cell: link marks on text nodes, plus bare url cards.
function collectLinks(n, acc) {
  if (!n || typeof n !== 'object') { return acc; }
  if (n.type === 'text' && Array.isArray(n.marks)) {
    for (let m = 0; m < n.marks.length; m++) {
      const mark = n.marks[m];
      if (mark && mark.type === 'link' && mark.attrs && mark.attrs.href) {
        acc.push({ text: n.text || '', href: mark.attrs.href });
      }
    }
  }
  if ((n.type === 'inlineCard' || n.type === 'blockCard') && n.attrs && n.attrs.url) {
    acc.push({ text: n.attrs.url, href: n.attrs.url });
  }
  const kids = n.content || [];
  for (let i = 0; i < kids.length; i++) { collectLinks(kids[i], acc); }
  return acc;
}

function collectTables(n, acc) {
  if (!n || typeof n !== 'object') { return acc; }
  if (n.type === 'table') { acc.push(n); }
  const kids = n.content || [];
  for (let i = 0; i < kids.length; i++) { collectTables(kids[i], acc); }
  return acc;
}

function primaryOwner(raw) {
  let s = (raw || '').replace(/\([^)]*\)/g, ' ');
  s = s.replace(/\s+/g, ' ').trim();
  if (!s) { return ''; }
  const parts = s.split(/[\/+,&]/);
  return parts[0].trim();
}

// opts: label, pageId, nameHeaders (accepted first-column headers), minRows, defaultCategory
function parsePage(page, opts) {
  const adfRaw = page && page.body && page.body.atlas_doc_format ? page.body.atlas_doc_format.value : null;
  if (!adfRaw) { throw new Error(opts.label + ' page ' + opts.pageId + ' returned no atlas_doc_format body. Offboarding aborted.'); }
  const doc = typeof adfRaw === 'string' ? JSON.parse(adfRaw) : adfRaw;

  // locate the table whose first header cell is one of the accepted name headers
  const tables = collectTables(doc, []);
  let target = null;
  let header = [];
  for (let t = 0; t < tables.length; t++) {
    const firstRow = (tables[t].content || [])[0];
    if (!firstRow) { continue; }
    const cells = firstRow.content || [];
    const texts = [];
    for (let c = 0; c < cells.length; c++) { texts.push(textOf(cells[c]).replace(/\s+/g, ' ').trim().toLowerCase()); }
    if (texts.length > 0 && opts.nameHeaders.indexOf(texts[0]) !== -1) { target = tables[t]; header = texts; break; }
  }
  if (!target) {
    throw new Error('Could not find the table on the ' + opts.label + ' page (' + opts.pageId + '): no table whose first column header is ' + opts.nameHeaders.map(function (h) { return '"' + h + '"'; }).join(' or ') + '. Offboarding aborted.');
  }

  // map columns by header name so added or reordered columns do not break the parse.
  // The first name found wins: the internal Note column is preferred over the public one.
  function findCol(names) {
    for (let n = 0; n < names.length; n++) { const i = header.indexOf(names[n]); if (i !== -1) { return i; } }
    return -1;
  }
  const COL_TOOL = 0;
  const COL_OWNER = findCol(['access owner', 'access owner [internal]']);
  const COL_NOTE = findCol(['note [internal]', 'note']);
  const COL_SCOPE = findCol(['scope', 'scope [internal]']);   // optional; -1 if absent
  const missing = [];
  if (COL_OWNER === -1) { missing.push('access owner'); }
  if (COL_NOTE === -1) { missing.push('note'); }
  if (missing.length > 0) {
    throw new Error(opts.label + ' table is missing required column(s): ' + missing.join(', ') + '. Columns found: ' + header.join(' | ') + '. Offboarding aborted.');
  }

  const allRows = target.content || [];
  const rows = [];
  let category = opts.defaultCategory || '';
  let categoryCount = 0;
  let linkedNoteCount = 0;
  let scopedCount = 0;
  for (let r = 1; r < allRows.length; r++) {
    const cells = allRows[r].content || [];
    const texts = [];
    for (let c = 0; c < cells.length; c++) { texts.push(textOf(cells[c]).replace(/\s+/g, ' ').trim()); }
    const baseTool = (texts[COL_TOOL] || '').trim();
    if (!baseTool) { continue; }
    let rest = '';
    for (let c = 0; c < texts.length; c++) { if (c !== COL_TOOL) { rest += (texts[c] || ''); } }
    if (rest.trim() === '') { category = baseTool; categoryCount++; continue; }

    const scope = COL_SCOPE >= 0 ? (texts[COL_SCOPE] || '').trim() : '';
    if (scope) { scopedCount++; }
    const tool = scope ? baseTool + ' (' + scope + ')' : baseTool;
    const ownerRaw = (texts[COL_OWNER] || '').trim();
    const noteLinks = cells.length > COL_NOTE ? collectLinks(cells[COL_NOTE], []) : [];
    if (noteLinks.length > 0) { linkedNoteCount++; }
    rows.push({ source: opts.label, category: category, tool: tool, scope: scope, note: (texts[COL_NOTE] || '').trim(), noteLinks: noteLinks, owner_confluence: ownerRaw, owner_key: primaryOwner(ownerRaw) });
  }

  if (rows.length < opts.minRows) {
    throw new Error('Only ' + rows.length + ' row(s) parsed from the ' + opts.label + ' page (expected at least ' + opts.minRows + '). Columns found: ' + header.join(' | ') + '. Offboarding aborted.');
  }
  return { header: header, rows: rows, categoryCount: categoryCount, linkedNoteCount: linkedNoteCount, scopedCount: scopedCount, version: page.version ? page.version.number : null };
}

const main = parsePage(mainPage, { label: 'General tools', pageId: '2076311575', nameHeaders: ['tool name'], minRows: 60, defaultCategory: '' });
const extra = parsePage(extraPage, { label: 'Offboarding additional steps', pageId: '2003894274', nameHeaders: ['section name', 'tool name', 'step', 'step name'], minRows: 0, defaultCategory: 'Additional steps' });

// The additional steps always sit at the very bottom. If one of its categories happens to share a name with
// the last General tools category, prefix it so the sheet still shows a separate heading.
const lastMainCategory = main.rows.length ? main.rows[main.rows.length - 1].category : '';
for (let i = 0; i < extra.rows.length; i++) {
  if (extra.rows[i].category === lastMainCategory) { extra.rows[i].category = 'Additional steps - ' + extra.rows[i].category; }
}

const rows = main.rows.concat(extra.rows);
const owners = [];
for (let i = 0; i < rows.length; i++) {
  const key = rows[i].owner_key;
  if (key && owners.indexOf(key) === -1) { owners.push(key); }
}

return [{ json: {
  pageVersion: main.version,
  additionalStepsPageVersion: extra.version,
  columns: main.header,
  additionalStepsColumns: extra.header,
  toolCount: rows.length,
  generalToolCount: main.rows.length,
  additionalStepCount: extra.rows.length,
  categoryCount: main.categoryCount + extra.categoryCount,
  scopedCount: main.scopedCount + extra.scopedCount,
  linkedNoteCount: main.linkedNoteCount + extra.linkedNoteCount,
  owners: owners,
  rows: rows
} }];

const parsed = $('Parse tools table').first().json;
const intake = $('Offboarding intake').first().json;
const rows = $input.all();
const map = {};
for (let i = 0; i < rows.length; i++) {
  const r = rows[i].json;
  if (r && r.confluence_owner) { map[String(r.confluence_owner).trim().toLowerCase()] = r.default_email ? String(r.default_email).trim() : ''; }
}

const fields = [];

// Timing follow-ups, asked only when the page 1 answer needs them.
const choice = String(intake['Offboarding can start'] || '').trim();
if (choice === 'On a specific date and time') {
  fields.push({ fieldLabel: 'Offboarding start date', fieldType: 'date', requiredField: true });
  fields.push({ fieldLabel: 'Offboarding start time (HH:MM, 24h)', fieldType: 'text', requiredField: true, placeholder: '17:00' });
} else if (choice.toLowerCase().indexOf('end of the working day') !== -1) {
  fields.push({ fieldLabel: 'Offboarding start date', fieldType: 'date', requiredField: true });
}

for (let i = 0; i < parsed.owners.length; i++) {
  const o = parsed.owners[i];
  const known = map[o.toLowerCase()] || '';
  fields.push({ fieldLabel: 'Email - ' + o, fieldType: 'email', defaultValue: known, requiredField: false, placeholder: 'leave empty if nobody should be pinged' });
  fields.push({ fieldLabel: 'Ping - ' + o, fieldType: 'checkbox', fieldOptions: { values: [{ option: 'Needed for this offboarding' }] }, defaultValue: 'Needed for this offboarding' });
}

const unknown = [];
for (let i = 0; i < parsed.owners.length; i++) {
  const o = parsed.owners[i];
  if (!map[o.toLowerCase()]) { unknown.push(o); }
}
return [{ json: { formFieldsJson: JSON.stringify(fields), owners: parsed.owners, unknownOwners: unknown, startChoice: choice } }];

const answers = $input.first().json;
const parsed = $('Parse tools table').first().json;
const intake = $('Offboarding intake').first().json;

const TEMPLATE_LAST_ROW = 400;
const BODY_START_ROW = 7;
const ZONE = 'Europe/Zagreb';
const END_OF_WORKING_DAY_HOUR = 18;

const firstName = String(intake['First name'] || '').trim();
const lastName = String(intake['Last name'] || '').trim();
const personName = (firstName + ' ' + lastName).trim();
const personEmail = String(intake['Work email'] || '').trim();
if (!personName || !personEmail) { throw new Error('Missing name or email from the intake form.'); }

const generatedAt = new Date().toISOString();

// --- when can offboarding start ---
const choice = String(intake['Offboarding can start'] || '').trim();
let offboardingStart = '';
let startDate = '';
let startTime = '';
let anchorAt = generatedAt;

function toIso(dateStr, hhmm) {
  if (typeof DateTime !== 'undefined') {
    const dt = DateTime.fromFormat(dateStr + ' ' + hhmm, 'yyyy-MM-dd HH:mm', { zone: ZONE });
    if (!dt.isValid) { throw new Error('Could not interpret "' + dateStr + ' ' + hhmm + '" as a date and time (' + dt.invalidReason + '). Nothing has been created.'); }
    return dt.toUTC().toISO();
  }
  const fallback = Date.parse(dateStr + 'T' + hhmm + ':00Z');
  if (!fallback) { throw new Error('Could not interpret "' + dateStr + ' ' + hhmm + '" as a date and time. Nothing has been created.'); }
  return new Date(fallback).toISOString();
}

if (choice === 'Immediately') {
  offboardingStart = 'Immediately';
  anchorAt = generatedAt;
} else {
  const raw = String(answers['Offboarding start date'] || '').trim();
  if (!raw) { throw new Error('Offboarding start date is missing but the selected option was "' + choice + '". Nothing has been created.'); }
  startDate = raw.length >= 10 ? raw.substring(0, 10) : raw;
  if (choice === 'On a specific date and time') {
    startTime = String(answers['Offboarding start time (HH:MM, 24h)'] || '').trim();
    if (!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(startTime)) {
      throw new Error('Offboarding start time must be HH:MM in 24-hour format (for example 17:00). Got "' + startTime + '". Nothing has been created.');
    }
    offboardingStart = startDate + ' ' + startTime + ' (' + ZONE + ')';
    anchorAt = toIso(startDate, startTime);
  } else {
    const hh = (END_OF_WORKING_DAY_HOUR < 10 ? '0' : '') + END_OF_WORKING_DAY_HOUR + ':00';
    offboardingStart = 'End of working day on ' + startDate;
    anchorAt = toIso(startDate, hh);
  }
}

// Reminders count from the offboarding start, but never from a moment already in the past.
let anchorSource = 'offboarding start';
if (Date.parse(anchorAt) <= Date.parse(generatedAt)) { anchorAt = generatedAt; anchorSource = 'checklist creation'; }

function isTicked(v) {
  if (v === true) { return true; }
  if (Array.isArray(v)) { return v.length > 0; }
  if (typeof v === 'string') { return v.trim() !== '' && v.trim().toLowerCase() !== 'false'; }
  return false;
}

const assignee = {};
const excluded = [];
const noEmail = [];
for (let i = 0; i < parsed.owners.length; i++) {
  const o = parsed.owners[i];
  const email = String(answers['Email - ' + o] || '').trim();
  const ping = isTicked(answers['Ping - ' + o]);
  if (!ping) { assignee[o] = ''; excluded.push(o); continue; }
  if (!email) { assignee[o] = ''; noEmail.push(o); continue; }
  assignee[o] = email;
}

function q(s) { return String(s === null || s === undefined ? '' : s).split('"').join('""'); }

// Rows 1-6 mirror the template's preamble and header, so the PATCH rewrites them with identical text.
const values = [];
values.push(['Name:', personName, '', '', '', '']);
values.push(['Email:', personEmail, '', '', '', '']);
values.push(['Offboarding can start:', offboardingStart, '', '', '', '']);
values.push(['Generated:', generatedAt, '', '', '', '']);
values.push(['', '', '', '', '', '']);
values.push(['Tool', 'Note', 'Access owner (Confluence)', 'Owner for this offboarding', 'Status', 'Status comments']);

const noteHyperlinks = [];
let multiLinkNotes = 0;
let lastCategory = '';
for (let i = 0; i < parsed.rows.length; i++) {
  const r = parsed.rows[i];
  if (r.category && r.category !== lastCategory) {
    values.push([r.category, '', '', '', '', '']);
    lastCategory = r.category;
  }
  const links = r.noteLinks || [];
  let noteText = r.note;
  if (links.length > 1) {
    // HYPERLINK carries a single target, so spell the rest out rather than lose them.
    multiLinkNotes++;
    const hrefs = [];
    for (let k = 0; k < links.length; k++) { hrefs.push(links[k].href); }
    noteText = r.note + ' [' + hrefs.join(' | ') + ']';
  }
  values.push([r.tool, noteText, r.owner_confluence, assignee[r.owner_key] || '', 'To do', '']);
  if (links.length === 1) {
    const label = r.note && r.note.trim() ? r.note : links[0].href;
    noteHyperlinks.push({ row: values.length, formula: '=HYPERLINK("' + q(links[0].href) + '","' + q(label) + '")' });
  }
}

const lastRow = values.length;
const bodyRows = lastRow - (BODY_START_ROW - 1);

// Hard stop: the template's dropdown and conditional formatting only cover E7:E400.
if (lastRow > TEMPLATE_LAST_ROW) {
  throw new Error('Checklist needs ' + lastRow + ' rows but the template only covers rows up to ' + TEMPLATE_LAST_ROW + ' (dropdown and conditional formatting on E7:E' + TEMPLATE_LAST_ROW + '). ' + parsed.rows.length + ' tools + ' + parsed.categoryCount + ' category rows were parsed from Confluence. Extend the template before running this offboarding - nothing has been created.');
}

const fileName = personName + ' - Offboarding.xlsx';
const rangeAddress = 'A1:F' + lastRow;

return [{ json: { personName: personName, personEmail: personEmail, offboardingStart: offboardingStart, startChoice: choice, startDate: startDate, startTime: startTime, anchorAt: anchorAt, anchorSource: anchorSource, fileName: fileName, generatedAt: generatedAt, worksheetName: 'Base tool checklist', toolCount: parsed.rows.length, categoryCount: parsed.categoryCount, bodyRows: bodyRows, lastRow: lastRow, rangeAddress: rangeAddress, hyperlinkCount: noteHyperlinks.length, multiLinkNotes: multiLinkNotes, noteHyperlinks: noteHyperlinks, pageVersion: parsed.pageVersion, assignee: assignee, excludedOwners: excluded.join(', '), ownersWithoutEmail: noEmail.join(', '), valuesBody: JSON.stringify({ values: values }), formRaw: JSON.stringify({ intake: intake, owners: answers }) } }];

const rec = $('Build offboarding record').first().json;
const file = $('Upload checklist to OneDrive').first().json;
const share = $('Create edit share link').first().json;
const parsed = $('Parse tools table').first().json;
const url = (share && share.link && share.link.webUrl) ? share.link.webUrl : (file.webUrl || '');

const byEmail = {};
for (let i = 0; i < parsed.rows.length; i++) {
  const r = parsed.rows[i];
  const email = rec.assignee[r.owner_key] || '';
  if (!email) { continue; }
  if (!byEmail[email]) { byEmail[email] = []; }
  byEmail[email].push(r.tool);
}

const out = [];
const emails = Object.keys(byEmail);
for (let i = 0; i < emails.length; i++) {
  const email = emails[i];
  const tools = byEmail[email];
  let text = '*Offboarding: ' + rec.personName + '* (' + rec.personEmail + ')\n';
  text += 'Offboarding can start: ' + rec.offboardingStart + '\n';
  text += 'Checklist: ' + url + '\n\n';
  text += 'You are the access owner for ' + tools.length + ' tool(s) on this checklist:\n';
  for (let t = 0; t < tools.length; t++) { text += '- ' + tools[t] + '\n'; }
  text += '\nPlease remove their access where needed and set each row to *Done* or *Not needed* in the Status column (pick from the dropdown).\n';
  if (rec.anchorSource === 'offboarding start') {
    text += 'Reminders for anything still *To do* begin once the offboarding start time is reached, then 6h, 12h, 24h and 48h after it.';
  } else {
    text += 'Reminders follow at 6h, 12h, 24h and 48h for anything still *To do*.';
  }
  out.push({ json: { email: email, toolCount: tools.length, text: text } });
}
return out;

const rec = $('Build offboarding record').first().json;
const file = $('Upload checklist to OneDrive').first().json;

const emails = [];
const keys = Object.keys(rec.assignee || {});
for (let i = 0; i < keys.length; i++) {
  const e = rec.assignee[keys[i]];
  if (e && emails.indexOf(e) === -1) { emails.push(e); }
}
const recipients = [];
for (let i = 0; i < emails.length; i++) { recipients.push({ email: emails[i] }); }
const inviteBody = { recipients: recipients, requireSignIn: true, sendInvitation: false, roles: ['write'] };

return [{ json: { fileId: file.id, fileWebUrl: file.webUrl || '', recipientCount: emails.length, inviteBody: JSON.stringify(inviteBody) } }];

const rec = $('Build offboarding record').first().json;
const file = $('Upload checklist to OneDrive').first().json;
const fileId = file.id;
const sheet = rec.worksheetName || 'Base tool checklist';
const base = '/me/drive/items/' + fileId + "/workbook/worksheets('" + sheet + "')";
const H = { 'Content-Type': 'application/json' };
const links = rec.noteHyperlinks || [];

// Graph caps a $batch at 20 sub-requests, so chunk and emit one item per chunk.
const CHUNK = 20;
const out = [];
for (let start = 0; start < links.length; start += CHUNK) {
  const reqs = [];
  for (let i = start; i < Math.min(start + CHUNK, links.length); i++) {
    reqs.push({ id: String(reqs.length + 1), method: 'PATCH', url: base + "/range(address='B" + links[i].row + "')", headers: H, body: { formulas: [[links[i].formula]] } });
  }
  out.push({ json: { chunk: out.length + 1, requestCount: reqs.length, batchBody: JSON.stringify({ requests: reqs }) } });
}

// Always emit one item so an empty link set cannot break the chain or send an empty batch.
if (out.length === 0) {
  out.push({ json: { chunk: 0, requestCount: 0, batchBody: JSON.stringify({ requests: [{ id: '1', method: 'GET', url: '/me/drive/items/' + fileId, headers: H }] }) } });
}
return out;

