if (Date.parse(anchorAt) <= Date.parse(generatedAt)) { anchorAt = generatedAt; anchorSource = 'checklist creation'; }

function isTicked(v) {
  if (v === true) { return true; }
  if (Array.isArray(v)) { return v.length > 0; }
  if (typeof v === 'string') { return v.trim() !== '' && v.trim().toLowerCase() !== 'false'; }
  return false;
}

const assignee = {};
