  let noteText = r.note;
  if (links.length > 1) {
    // HYPERLINK carries a single target, so spell the rest out rather than lose them.
    multiLinkNotes++;
    const hrefs = [];
    for (let k = 0; k < links.length; k++) { hrefs.push(links[k].href); }
    noteText = r.note + ' [' + hrefs.join(' | ') + ']';
  }
  values.push([r.tool, noteText, r.owner_confluence, assignee[r.owner_key] || '', 'To do', '']);
  if (links.length === 1) {
    const label = r.note && r.note.trim() ? r.note : links[0].href;
    noteHyperlinks.push({ row: values.length, formula: '=HYPERLINK("' + q(links[0].href) + '","' + q(label) + '")' });
  }
}

const lastRow = values.length;
const bodyRows = lastRow - (BODY_START_ROW - 1);

// Hard stop: the template's dropdown and conditional formatting only cover E7:E400.
if (lastRow > TEMPLATE_LAST_ROW) {
